    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '201: A "loculated" pleural effusion is most common in the setting of:', '["Heart failure", "Empyema or malignancy", "Pulmonary embolism", "Hypoalbuminemia"]', 1, 'Inflammation and infection cause adhesions (loculations), which prevent the fluid from moving freely.'),
    (v_topic_id, '202: "Vanishing tumor" (pseudotumor) of the lung refers to:', '["A rapidly growing cancer", "A loculated pleural effusion in a fissure (usually the minor fissure) that resolves with heart failure treatment", "A lung abscess", "Atelectasis"]', 1, 'These lenticular fluid collections can mimic a mass but disappear once the patient is diuresed.'),
    (v_topic_id, '203: "Fibrothorax" is characterized by:', '["Active pneumonia", "Extensive thickening and calcification of the pleura, often following an empyema or hemothorax", "Fluid in the hila", "Heart failure"]', 1, 'This "peel" can restrict lung expansion and require surgical decortication.'),
    (v_topic_id, '204: "Pericardial effusion" can be distinguished from cardiomegaly on CXR by:', '["The lack of pulmonary vascular congestion despite a massive heart shadow", "The presence of Kerley B lines", "Cephalization", "Air bronchograms"]', 0, 'In simple cardiomegaly (CHF), the lungs are usually congested. In pericardial effusion, the lungs are often surprisingly clear.'),
    (v_topic_id, '205: "Left Atrial Enlargement" (LAE) is classically associated with which CXR sign?', '["A \"Double density\" sign on the right heart border and splaying of the carina", "A boat-shaped heart", "Rib notching", "Flattened diaphragms"]', 0, 'The enlarged left atrium pushes past the right atrium (double density) and pushes the main bronchi apart.'),
    (v_topic_id, '206: "Right Ventricular Hypertrophy" (RVH) is best visualized on which CXR view?', '["PA view (it looks small)", "Lateral view (filling of the retrosternal clear space)", "Lordotic view", "Decubitus view"]', 1, 'Because the RV is an anterior structure, its enlargement fills the space between the heart and the sternum.'),
    (v_topic_id, '207: "Cardiomegaly" on an AP (Anteroposterior) film is often:', '["Underestimated", "Overestimated (due to magnification)", "More accurate", "Impossible to see"]', 1, 'The closer the heart is to the X-ray source, the larger it appears. AP films should be interpreted cautiously regarding heart size.'),
    (v_topic_id, '208: A "Wide Mediastinum" in a trauma patient is defined as a width greater than:', '["5 cm", "8 cm", "10 cm", "12 cm"]', 1, 'A width > 8 cm at the level of the aortic knob is highly suspicious for aortic injury.'),
    (v_topic_id, '209: The "Left Subclavian Artery" is the most common site for which traumatic injury?', '["Aortic dissection", "Aortic transection (near the ligamentum arteriosum)", "Rib fractures", "Pneumothorax"]', 1, 'The aorta is relatively fixed at this point, making it vulnerable to deceleration injuries.'),
    (v_topic_id, '210: "Pneumomediastinum" is most commonly caused by:', '["Heart failure", "Alveolar rupture (Macklin effect) or esophageal rupture (Boerhaave)", "Pneumonia", "Lung cancer"]', 1, 'Air tracks from ruptured alveoli or the esophagus into the mediastinal space.'),
    (v_topic_id, '211: "Boerhaave Syndrome" (esophageal rupture) classically presents with which radiographic triad?', '["Pneumothorax, rib fractures, and edema", "Left-sided pleural effusion, pneumomediastinum, and hydropneumothorax", "Water-bottle heart, edema, and B-lines", "Normal CXR"]', 1, 'Esophageal contents leak into the mediastinum and pleura, usually on the left.'),
    (v_topic_id, '212: "Hydropneumothorax" refers to the presence of:', '["Both air and fluid in the pleural space", "Blood and pus", "Air in the heart", "Fluid in the hila"]', 0, 'This is characterized by a "straight-line" horizontal interface on an upright film.'),
    (v_topic_id, '213: If you see an air-fluid level in the pleural space, you must consider:', '["Bronchopleural fistula", "Recent thoracentesis (air introduced)", "Esophageal rupture", "All of the above"]', 3, 'An air-fluid level implies that gas has entered the pleural space alongside fluid.'),
    (v_topic_id, '214: "Lung Cancer" (Bronchogenic Carcinoma) is the leading cause of "Superior Vena Cava (SVC) Syndrome." What is the classic CXR finding?', '["Right paratracheal widening or a right hilar mass", "Left ventricular enlargement", "Rib notching", "Blunted angles"]', 0, 'A mass in the right upper mediastinum compresses the SVC.'),
    (v_topic_id, '215: "Pancoast Tumor" (Superior Sulcus Tumor) is located at the:', '["Base of the lung", "Apex of the lung", "Hilum", "Pleural space"]', 1, 'These tumors often invade the brachial plexus and sympathetic chain, causing Horner''s syndrome.'),
    (v_topic_id, '216: A "Central Line" (CVC) that is placed too far can cause:', '["Atrial arrhythmias or cardiac perforation", "Pneumonia", "Atelectasis", "Rib fractures"]', 0, 'The tip should be in the SVC, not the right atrium.'),
    (v_topic_id, '217: A "Swan-Ganz" (Pulmonary Artery) catheter tip should ideally be located:', '["In the right atrium", "Within the proximal right or left pulmonary artery (no more than 2 cm from the hilum)", "In the SVC", "In the left ventricle"]', 1, 'If it is too distal, it can cause pulmonary artery rupture or infarction.'),
    (v_topic_id, '218: "Intra-aortic Balloon Pump" (IABP) tip should be positioned:', '["In the ascending aorta", "Just distal to the origin of the left subclavian artery", "Below the renal arteries", "In the heart"]', 1, 'This maximizes diastolic augmentation while avoiding occlusion of the great vessels.'),
    (v_topic_id, '219: A "Chest Tube" (thoracostomy tube) for pneumothorax should be aimed:', '["Superiorly and anteriorly", "Inferiorly and posteriorly", "Toward the heart", "Downward"]', 0, 'Air rises to the top of the chest.'),
    (v_topic_id, '220: A "Chest Tube" for pleural effusion or empyema should be aimed:', '["Superiorly", "Inferiorly and posteriorly", "Anteriorly", "Toward the trachea"]', 1, 'Fluid pools at the bottom and back of the chest.'),
    (v_topic_id, '221: "Pacemaker" leads are most commonly seen in which two chambers?', '["Left atrium and left ventricle", "Right atrium and right ventricle", "Right atrium and left ventricle", "SVC and Aorta"]', 1, 'Standard dual-chamber pacemakers use the right-sided chambers.'),
    (v_topic_id, '222: "Twiddler''s Syndrome" refers to a patient:', '["Moving too much during an X-ray", "Manipulating their pacemaker pulse generator, causing the leads to coil and dislodge", "Having a heart that swings in fluid", "Coughing up a lot of mucus"]', 1, 'This results in lead failure and potentially diaphragmatic pacing.'),
    (v_topic_id, '223: "Diaphragmatic Paralysis" (e.g., from phrenic nerve injury) is best diagnosed by which radiographic test?', '["Standard CXR", "Fluoroscopic \"Sniff Test\"", "MRI", "CT scan"]', 1, 'Paradoxical upward movement of the affected hemidiaphragm during a quick inspiration (sniff) is diagnostic.'),
    (v_topic_id, '224: "Eventration" of the diaphragm is:', '["A true hernia", "A focal area of thinning and weakness of the diaphragm muscle, causing it to bulge upward", "A tumor of the diaphragm", "A rib fracture"]', 1, 'This is a benign, usually congenital finding that can mimic a mass or hernia.'),
    (v_topic_id, '225: "Hiatal Hernia" appears on CXR as:', '["A retrocardiac air-fluid level or soft tissue mass", "Air under the right hemidiaphragm", "A wide mediastinum", "A lung nodule"]', 0, 'The stomach herniates through the esophageal hiatus into the posterior mediastinum.'),
    (v_topic_id, '226: "Bochdalek Hernia" is a congenital diaphragmatic hernia that is most common on the:', '["Right side, anteriorly", "Left side, posteriorly", "Right side, posteriorly", "Left side, anteriorly"]', 1, 'Mnemonic: "B"ochdalek is "B"ack and to the left.'),
    (v_topic_id, '227: "Morgagni Hernia" is a congenital diaphragmatic hernia that is most common on the:', '["Right side, anteriorly", "Left side, posteriorly", "Left side, anteriorly", "Right side, posteriorly"]', 0, 'Morgagni is anterior.'),
    (v_topic_id, '228: "Chest Trauma" can cause "Pulmonary Contusion." How quickly does this appear on CXR?', '["Immediately to within 6 hours", "After 24 hours", "After 48 hours", "It doesn''t show on CXR"]', 0, 'Contusions (bruising/hemorrhage) appear rapidly after injury, unlike pneumonia which takes longer to develop.'),
    (v_topic_id, '229: A "Flail Chest" is defined by:', '["One rib fracture", "Three or more adjacent ribs fractured in two or more places", "Any rib fracture", "A sternal fracture"]', 1, 'This causes paradoxical motion of the chest wall during breathing.'),
    (v_topic_id, '230: "Rib Fractures" (1st to 3rd ribs) are clinically significant because:', '["They are very painful", "They indicate high-energy trauma and increased risk of injury to the great vessels or airway", "They cause pneumonia", "They are easy to fix"]', 1, 'The upper ribs are well-protected; their fracture implies severe force.'),
    (v_topic_id, '231: "Rib Fractures" (9th to 12th ribs) should raise suspicion for injury to which organs?', '["Lungs", "Liver or Spleen", "Heart", "Esophagus"]', 1, 'These lower ribs overlie the upper abdominal solid organs.'),
    (v_topic_id, '232: "Aortic Dissection" is best diagnosed with:', '["Plain CXR", "Contrast-enhanced CT Angiography (CTA)", "Ultrasound", "Barium swallow"]', 1, 'CTA can visualize the "intimal flap" separating the true and false lumens.'),
    (v_topic_id, '233: "Aortic Dissection" classification: A "Stanford Type A" dissection involves:', '["The descending aorta only", "The ascending aorta (regardless of distal extension)", "The abdominal aorta", "The iliac arteries"]', 1, 'Type A is a surgical emergency.'),
    (v_topic_id, '234: "Aortic Dissection" classification: A "Stanford Type B" dissection involves:', '["The ascending aorta", "The descending aorta only (distal to the left subclavian)", "The heart", "The neck"]', 1, 'Type B is often managed medically (blood pressure control).'),
    (v_topic_id, '235: "Pericardial calcification" is the radiographic hallmark of:', '["Acute pericarditis", "Constrictive pericarditis", "Heart failure", "Aortic stenosis"]', 1, 'The "eggshell" encasement of the heart prevents normal diastolic filling.'),
    (v_topic_id, '236: "Mitral Stenosis" can cause which specific radiographic sign on a lateral CXR?', '["Posterior displacement of the esophagus by an enlarged left atrium", "Anterior displacement of the heart", "Widened hila", "Rib notching"]', 0, 'This is best seen on a lateral view with barium swallow.'),
    (v_topic_id, '237: "Ebstein''s Anomaly" on CXR often shows a "Box-shaped" heart. What causes this?', '["Massive Right Atrial enlargement", "Left Ventricular Hypertrophy", "Aortic aneurysm", "Pleural effusion"]', 0, 'The tricuspid valve is displaced, leading to an enormous RA.'),
    (v_topic_id, '238: "Coarctation of the Aorta" can show the "3 sign" on CXR. What forms the 3?', '["The ribs", "The pre-stenotic aorta, the site of coarctation, and the post-stenotic dilation", "The trachea", "The hila"]', 1, 'The aortic contour is indented at the site of the narrowing.'),
    (v_topic_id, '239: "Tetralogy of Fallot" (TOF) classically shows a "Boot-shaped heart" because of:', '["Right Ventricular Hypertrophy and a small Pulmonary Artery", "Left Ventricular enlargement", "Aortic dissection", "Large hila"]', 0, 'The upturned apex is due to RVH, and the "concaver" pulmonary segment is due to stenosis.'),
    (v_topic_id, '240: "Scimitar Syndrome" is a form of partial anomalous pulmonary venous return (PAPVR). What is the scimitar?', '["A rib", "An anomalous pulmonary vein draining into the IVC, resembling a curved Turkish sword", "A lung tumor", "A hole in the diaphragm"]', 1, 'It is seen on the right side, tracking down toward the diaphragm.'),
    (v_topic_id, '241: On a CXR, a "Lutembacher Syndrome" patient might show:', '["Heart failure and RAD", "Signs of Atrial Septal Defect and Mitral Stenosis", "Pneumonia", "Aorta widening"]', 1, 'This is the combination of ASD and MS.'),
    (v_topic_id, '242: "Dextrocardia" is definitively diagnosed when:', '["The apex of the heart is on the right side of the chest", "The stomach is on the right", "The hila are large", "The patient has a cough"]', 0, 'It must be distinguished from "Dextroposition" (where the heart is pushed to the right by pathology).'),
    (v_topic_id, '243: "Situs Inversus Totalis" means:', '["Only the heart is reversed", "All thoracic and abdominal organs are mirror images of normal", "The lungs are upside down", "The leads were reversed by the technician"]', 1, 'This is often asymptomatic and found incidentally.'),
    (v_topic_id, '244: "Kartagener Syndrome" consists of situs inversus, chronic sinusitis, and:', '["Pneumonia", "Bronchiectasis (due to primary ciliary dyskinesia)", "Heart failure", "Diabetes"]', 1, 'Immotile cilia lead to poor mucus clearance.'),
    (v_topic_id, '245: A "Lobar pneumonia" that does NOT improve after 4-6 weeks of treatment should be evaluated for:', '["Underlying malignancy (obstructing the bronchus)", "Tuberculosis", "A foreign body", "All of the above"]', 3, 'Non-resolving pneumonia is a "red flag."'),
    (v_topic_id, '246: "Lipoid Pneumonia" is caused by:', '["Bacterial infection", "Aspiration of mineral oil or fatty substances", "Smoking", "Fungal infection"]', 1, 'On CT, these opacities show characteristic low (fat) density.'),
    (v_topic_id, '247: "Pulmonary Alveolar Microlithiasis" is a rare condition showing:', '["Massive tumors", "Diffuse, fine sand-like calcifications throughout the lungs (\"sandstorm\")", "Rib fractures", "Large cavities"]', 1, 'The radiographic appearance is much more dramatic than the patient''s symptoms.'),
    (v_topic_id, '248: "Pulmonary Sequestration" is a segment of lung tissue that:', '["Is infected", "Does not communicate with the bronchial tree and has an anomalous systemic blood supply", "Is missing", "Is part of the pleura"]', 1, 'It is usually found at the left lung base.'),
    (v_topic_id, '249: "Bronchogenic Cyst" is a congenital lesion usually found in the:', '["Lung apex", "Middle mediastinum (near the carina)", "Pleural space", "Abdomen"]', 1, 'It is a fluid-filled remnant of the primitive foregut.'),
    (v_topic_id, '250: "Tracheal Deviation" AWAY from an opacity suggests:', '["Atelectasis", "A large pleural effusion or tension pneumothorax (mass effect)", "Pneumonia", "Lung fibrosis"]', 1, 'Mass effect "pushes" the trachea.'),
    (v_topic_id, '251: "Tracheal Deviation" TOWARD an opacity suggests:', '["Pleural effusion", "Atelectasis (volume loss) or previous pneumonectomy", "Tension pneumothorax", "Pericarditis"]', 1, 'Volume loss "pulls" the trachea.'),
    (v_topic_id, '252: "Swyer-James Syndrome" is a radiographic diagnosis of:', '["A large heart", "Unilateral hyperlucent lung due to post-infectious bronchiolitis obliterans", "Bilateral pneumonia", "Rib notching"]', 1, 'The affected lung is smaller and clearer because of decreased blood flow and air trapping.'),
    (v_topic_id, '253: "Widespread miliary nodules" in a patient from the Ohio/Mississippi River Valley should raise suspicion for:', '["Histoplasmosis", "TB", "Sarcoidosis", "Silicosis"]', 0, 'This fungal infection is endemic to these regions.'),
    (v_topic_id, '254: "Coccidioidomycosis" (Valley Fever) is endemic to:', '["Northeast US", "Southwest US (Arizona/California)", "Florida", "England"]', 1, 'It often causes thin-walled cavities and hilar nodes.'),
    (v_topic_id, '255: "Hydatid Cyst" (Echinococcus) in the lung classically appears as:', '["A small nodule", "A large, well-defined water-density cyst that may have a detached internal membrane (\"Water-lily sign\")", "Diffuse edema", "A rib fracture"]', 1, 'This is a parasitic infection often seen in sheep-raising regions.'),
    (v_topic_id, '256: "Mesothelioma" is the only cancer that is almost exclusively related to:', '["Smoking", "Asbestos", "Alcohol", "Radon"]', 1, 'It takes 20-40 years to develop after exposure.'),
    (v_topic_id, '257: A "Calcified Pleural Plaque" is a sign of:', '["Active mesothelioma", "Prior asbestos exposure (benign)", "Tuberculosis", "Pneumonia"]', 1, 'The presence of plaques does NOT mean the patient has cancer, but it proves they were exposed to asbestos.'),
    (v_topic_id, '258: "Pleural effusion" in a patient with Asbestos exposure is called "Benign Asbestos Pleural Effusion" (BAPE). It is a diagnosis of:', '["Exclusion", "Inclusion", "Certainty", "None"]', 0, 'One must first rule out malignancy and infection.'),
    (v_topic_id, '259: The "Light''s Criteria" are used to distinguish:', '["Heart failure from pneumonia", "Exudative from transudative pleural effusions", "Malignancy from TB", "Pneumothorax from edema"]', 1, 'This requires biochemical analysis of the pleural fluid, not just imaging.'),
    (v_topic_id, '260: A "Transudative" effusion is most commonly caused by:', '["Pneumonia", "Congestive Heart Failure or Cirrhosis", "Cancer", "Pulmonary Embolism"]', 1, 'These are due to systemic pressure changes, not local pleural disease.'),
    (v_topic_id, '261: An "Exudative" effusion is most commonly caused by:', '["Pneumonia (Parapneumonic), Malignancy, or PE", "Cirrhosis", "Nephrotic syndrome", "Atelectasis"]', 0, 'These are due to local inflammation or malignancy increasing capillary permeability.'),
    (v_topic_id, '262: "Pseudopneumoperitoneum" can be caused by:', '["Chilaiditi Syndrome (interposition of colon between liver and diaphragm)", "Atelectasis", "Heart failure", "Pneumonia"]', 0, 'Haustral markings within the "air" help distinguish this from true free air.'),
    (v_topic_id, '263: "Chilaiditi Syndrome" is usually:', '["A surgical emergency", "An incidental, asymptomatic finding", "Associated with colon cancer", "A sign of liver failure"]', 1, 'No treatment is needed.'),
    (v_topic_id, '264: "Staghorn Calculus" is a large kidney stone that:', '["Is in the bladder", "Fills the renal pelvis and calyces, resembling deer antlers", "Is made of sugar", "Is invisible on X-ray"]', 1, 'These are usually struvite (infection) stones.'),
    (v_topic_id, '265: "Nephrocalcinosis" refers to:', '["A single kidney stone", "Diffuse calcification within the renal parenchyma", "A kidney tumor", "Kidney failure"]', 1, 'This is seen in conditions like Medullary Sponge Kidney or Hyperparathyroidism.'),
    (v_topic_id, '266: "Pneumatosis Intestinalis" is air:', '["In the bowel lumen", "Within the wall of the bowel", "In the peritoneal cavity", "In the liver"]', 1, 'This is a worrisome sign of bowel ischemia or necrosis (e.g., Necrotizing Enterocolitis in infants).'),
    (v_topic_id, '267: "Portal Venous Gas" appears as:', '["Branching air within the periphery of the liver", "Air in the center of the liver", "Gallstones", "Ascites"]', 0, 'This is a very ominous sign of advanced bowel ischemia.'),
    (v_topic_id, '268: "Sentinel Loop" of bowel in the Left Upper Quadrant is associated with:', '["Appendicitis", "Pancreatitis", "Cholecystitis", "Diverticulitis"]', 1, 'The loop of jejunum becomes paralyzed by nearby inflammation.'),
    (v_topic_id, '269: "Abdominal Ascites" on a plain film appears as:', '["Increased bowel air", "Diffuse haziness and \"ground-glass\" appearance of the abdomen with central floating bowel loops", "Pneumatosis", "Large masses"]', 1, 'The fluid makes the whole abdomen look dense and grey.'),
    (v_topic_id, '270: "Dog-ears" appearance on a pelvic X-ray refers to:', '["Fluid in the recesses of the pelvis (paravesical fossae) due to ascites", "A bladder tumor", "Uterine fibroids", "Hip fractures"]', 0, 'This is an older radiographic sign of pelvic fluid.'),
    (v_topic_id, '271: "Phleboliths" are small, round calcifications in the pelvis that represent:', '["Kidney stones", "Calcified pelvic veins (benign)", "Appendicoliths", "Bladder stones"]', 1, 'They are very common and often confused with ureteral stones.'),
    (v_topic_id, '272: How do you distinguish a "Phlebolith" from a "Ureteral stone"?', '["Phleboliths often have a radiolucent center", "Ureteral stones are always black", "Phleboliths are always in the kidney", "There is no way to tell"]', 0, 'The lucent center is a classic benign feature of a phlebolith.'),
    (v_topic_id, '273: "Appendicolith" is a calcified stone in the appendix. If seen in a patient with RLQ pain, it is:', '["Meaningless", "Highly suggestive of Appendicitis", "A gallstone", "A kidney stone"]', 1, 'It suggests an obstructed appendix.'),
    (v_topic_id, '274: "Small Bowel" loops are normally located in the:', '["Periphery of the abdomen", "Center of the abdomen", "Pelvis only", "Upper quadrants only"]', 1, 'The colon occupies the periphery.'),
    (v_topic_id, '275: "Large Bowel" (Colon) is normally located in the:', '["Center", "Periphery", "Chest", "Against the spine"]', 1, 'The colon "frames" the small bowel.'),
    (v_topic_id, '276: "Toxic Megacolon" is characterized by:', '["A small colon", "Massive dilation of the colon (> 6 cm) in the setting of severe colitis", "Pneumoperitoneum", "Gallstones"]', 1, 'This is a life-threatening complication of IBD or C. difficile infection.'),
    (v_topic_id, '277: "Barium Swallow" (Esophagram) is used to evaluate:', '["The stomach", "The esophagus (swallowing mechanism, strictures, tumors)", "The colon", "The rectum"]', 1, 'It provides dynamic information about the esophagus.'),
    (v_topic_id, '278: "Upper GI Series" (UGI) evaluates the:', '["Esophagus only", "Esophagus, Stomach, and Duodenum", "Small bowel only", "Colon"]', 1, 'It uses contrast to visualize the upper digestive tract.'),
    (v_topic_id, '279: "Barium Enema" (BE) is used to evaluate the:', '["Stomach", "Small bowel", "Large bowel (Colon)", "Gallbladder"]', 2, 'It has largely been replaced by CT and colonoscopy but can still be useful for certain conditions like volvulus.'),
    (v_topic_id, '280: "Double-contrast" study involves using:', '["Two types of barium", "Barium + Air", "Barium + Water", "Barium + Iodine"]', 1, 'Air distends the lumen, allowing for better visualization of the mucosal surface.'),
    (v_topic_id, '281: "Gastrografin" is a water-soluble contrast medium used when:', '["Barium is too expensive", "A perforation is suspected (as barium causes severe peritonitis)", "The patient is allergic to iodine", "The patient has asthma"]', 1, 'Barium should NEVER be given if a leak or perforation is suspected.'),
    (v_topic_id, '282: "Hounsfield Units" (HU) are used in CT to measure:', '["Size", "Density (Attenuation)", "Speed", "Radiation dose"]', 1, 'Water is defined as 0 HU, Air as -1000 HU, and Bone as +1000 HU.'),
    (v_topic_id, '283: "Windowing" in CT refers to:', '["Looking through a window", "Adjusting the range of HU displayed to highlight specific tissues (e.g., lung vs. bone window)", "Changing the patient''s position", "Turning the machine off"]', 1, 'A "Lung Window" makes the lungs look good but the heart look like a white blob; a "Mediastinal Window" does the opposite.'),
    (v_topic_id, '284: "IV Contrast" in CT is usually:', '["Barium-based", "Iodine-based", "Gadolinium-based", "Water"]', 1, 'Iodine is radiopaque and highlights the vascular system.'),
    (v_topic_id, '285: "Gadolinium" is the contrast agent used for:', '["X-ray", "CT", "MRI", "Ultrasound"]', 2, 'Gadolinium has paramagnetic properties.'),
    (v_topic_id, '286: "CT Pulmonary Angiogram" (CTPA) requires:', '["Fast injection of IV contrast and precise timing (bolus tracking)", "Barium swallow", "The patient to run", "No contrast"]', 0, 'The scan must occur exactly when the contrast is in the pulmonary arteries.'),
    (v_topic_id, '287: "Magnetic Resonance Imaging" (MRI) is superior to CT for evaluating:', '["Bones", "Soft tissues, brain, and spinal cord", "Lung parenchyma", "Pneumoperitoneum"]', 1, 'MRI provides excellent soft tissue contrast.'),
    (v_topic_id, '288: The main contraindication for an MRI is:', '["Asthma", "Ferromagnetic implants (e.g., older pacemakers or shrapnel)", "Iodine allergy", "Pregnancy"]', 1, 'The powerful magnet can pull or heat up metal objects.'),
    (v_topic_id, '289: "Ultrasound" (US) uses _____ to create images.', '["X-rays", "High-frequency sound waves", "Magnets", "Gamma rays"]', 1, 'It is safe, portable, and involves no ionizing radiation.'),
    (v_topic_id, '290: "Anechoic" (black) on Ultrasound means:', '["The tissue reflects all sound", "The sound passes through without reflection (typical of simple fluid/water)", "There is air", "There is bone"]', 1, 'Cysts and the bladder are typically anechoic.'),
    (v_topic_id, '291: "Hyperechoic" (bright white) on Ultrasound is characteristic of:', '["Water", "Bone, stones, and fat", "Cysts", "Muscle"]', 1, 'Solid/dense structures reflect more sound.'),
    (v_topic_id, '292: "Acoustic Shadowing" on US is a dark void behind a structure, indicating that the structure is:', '["Very soft", "Extremely dense (like a gallstone or bone) and reflects/absorbs all sound", "Full of air", "Transparent"]', 1, 'This is a key feature for identifying stones.'),
    (v_topic_id, '293: "Nuclear Medicine" scans (like a V/Q scan or Bone scan) involve:', '["External X-rays", "Injection of a radioactive tracer that is detected by a gamma camera", "Magnets", "Sound waves"]', 1, 'This evaluates "function" rather than just "anatomy."'),
    (v_topic_id, '294: A "V/Q Mismatch" (normal ventilation, abnormal perfusion) is the hallmark of:', '["Pneumonia", "Pulmonary Embolism", "Asthma", "Lung cancer"]', 1, 'Air gets in, but blood does not.'),
    (v_topic_id, '295: "Positron Emission Tomography" (PET) scans most commonly use:', '["Radioactive Iodine", "18-FDG (a radioactive sugar analog)", "Barium", "Gadolinium"]', 1, 'Tissues with high metabolic activity (like cancer or inflammation) "take up" the sugar and glow on the scan.'),
    (v_topic_id, '296: "Interventional Radiology" (IR) involves:', '["Just reading scans", "Minimally invasive procedures guided by imaging (e.g., biopsy, drainage, stenting)", "Surgery only", "Giving medications"]', 1, 'IR uses "live" X-ray (fluoroscopy) or CT/US to guide tools.'),
    (v_topic_id, '297: "Pneumobilia" (air in the bile ducts) is best seen in which part of the liver?', '["The periphery", "The center/hilum", "The bottom", "Everywhere"]', 1, 'Bile flows toward the center, so air collects centrally (unlike portal venous gas which is peripheral).'),
    (v_topic_id, '298: "Fecaliths" (stones made of stool) are common in the:', '["Esophagus", "Stomach", "Appendix or diverticula", "Lungs"]', 2, 'They can cause obstruction and inflammation.'),
    (v_topic_id, '299: "Ventriculoperitoneal (VP) Shunt" is a tube seen on X-ray that drains fluid from the:', '["Heart", "Brain (ventricles) into the peritoneum", "Lungs", "Kidneys"]', 1, 'It is used to treat hydrocephalus.'),
    (v_topic_id, '300: "Mammography" uses _____ to screen for breast cancer.', '["MRI", "Low-dose X-rays", "Ultrasound", "CT"]', 1, 'It is the gold standard for screening.');
